  ('lea', '00000000-0000-4000-a000-00000000a003'::uuid, 'lea@bonded.test', 'Lea', 'Europe/Paris', 'en', 'ios'),
  ('eve', '00000000-0000-4000-a000-00000000a004'::uuid, 'eve@bonded.test', 'Eve', 'Asia/Tokyo', 'en', 'android'),
  ('finn', '00000000-0000-4000-a000-00000000a005'::uuid, 'finn@bonded.test', 'Finn', 'Asia/Tokyo', 'en', 'ios'),
  ('noor', '00000000-0000-4000-a000-00000000a006'::uuid, 'noor@bonded.test', 'Noor', 'Australia/Sydney', 'en', 'ios')
on conflict (key) do update set id = excluded.id, email = excluded.email, display_name = excluded.display_name,
  timezone = excluded.timezone, locale = excluded.locale, platform = excluded.platform;
