  ('eve_finn', '00000000-0000-4000-b000-0000000000c2'::uuid, array['eve', 'finn']::text[], 'Asia/Tokyo', 'living_together', array['romance']::text[], null),
  ('lea_solo', '00000000-0000-4000-b000-0000000000c3'::uuid, array['lea']::text[], 'Europe/Paris', 'dating', array['learning_about_each_other']::text[], null)
on conflict (key) do update set id = excluded.id, members = excluded.members, timezone = excluded.timezone, stage = excluded.stage,
